insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_ss_v1'
from (values
('113.18.c.1.A',3,'Many countries in South Asia use English in government and business. Which historical event best explains this?','["British colonial rule", "the invention of the printing press", "the Cold War space race", "the Silk Road"]'::jsonb,0,'Britain ruled much of South Asia for about 200 years.','original'),
('113.18.c.1.A',3,'Why do many people in Brazil speak Portuguese instead of Spanish?','["Brazil was part of the Roman Empire", "Portugal colonized Brazil", "Portuguese was invented there", "Spain traded with Brazil"]'::jsonb,1,'Colonial history shaped language.','original'),
('113.18.c.1.A',4,'Why are many borders in Africa straight lines?','["Mountains formed them", "Africans designed them as squares", "European powers drew them with little regard for ethnic groups", "Rivers formed them"]'::jsonb,2,'Colonial boundaries often ignored local cultures.','original'),
('113.18.c.1.B',4,'A region with a long history of trade along ports is most likely to have...','["no cities", "no outside influence", "only one religion", "diverse cultures and languages"]'::jsonb,3,'Trade brings cultural contact.','original'),
('113.18.c.1.B',3,'Why might knowing a country''s past help explain present-day conflicts?','["past events can shape borders, grievances and alliances", "only maps matter", "conflicts have no causes", "the past never affects the present"]'::jsonb,0,'History explains current tensions.','original'),
('113.18.c.2.A',3,'Mahatma Gandhi influenced India by leading...','["a trade empire", "nonviolent resistance to British rule", "a space program", "a naval invasion"]'::jsonb,1,'Gandhi used peaceful protest.','original'),
('113.18.c.2.A',3,'Nelson Mandela is known for...','["leading the Mongol army", "inventing the telephone", "ending apartheid and becoming South Africa''s president", "founding the Roman Republic"]'::jsonb,2,'He worked against racial segregation.','original'),
('113.18.c.2.B',3,'Which is a cultural contribution of ancient Greece to modern societies?','["the printing press", "gunpowder", "paper money in Europe", "ideas about democracy and philosophy"]'::jsonb,3,'Greek ideas shaped modern government.','original'),
('113.18.c.2.B',3,'Which group is credited with developing the numeral system used worldwide today, including zero?','["mathematicians in India", "medieval knights", "Vikings", "Aztec farmers"]'::jsonb,0,'Hindu-Arabic numerals began in India.','original'),
('113.18.c.3.A',3,'Which factor most often explains why a large city grows next to a river?','["it is far from resources", "access to water, farming and trade routes", "lack of fresh water", "steep deserts"]'::jsonb,1,'Resources attract settlement.','original'),
('113.18.c.3.A',3,'Why are few people living in the Sahara?','["it has too many rivers", "it is underwater", "it is a hot, dry desert with little water", "it is frozen"]'::jsonb,2,'Climate limits population.','original'),
('113.18.c.3.A',4,'A region with fertile soil and a mild climate will most likely have a...','["no farming", "very small population", "no towns", "dense population"]'::jsonb,3,'Good land supports many people.','original'),
('113.18.c.3.B',3,'How can large-scale migration change a city?','["it can add new languages, foods and traditions", "it freezes culture", "it removes all history", "it stops trade"]'::jsonb,0,'Migrants change the character of places.','original'),
('113.18.c.3.B',3,'Immigrants moving to a city for jobs are called...','["tourists only", "economic migrants", "explorers only", "cartographers"]'::jsonb,1,'They move for work.','original'),
('113.18.c.3.C',2,'Which is a major physical feature of South America?','["the Nile River", "the Alps", "the Amazon River", "the Gobi Desert"]'::jsonb,2,'The Amazon is in South America.','original'),
('113.18.c.3.C',2,'Which landform separates Europe and Asia?','["the Rockies", "the Andes", "the Sahara", "the Ural Mountains"]'::jsonb,3,'The Urals are a traditional boundary.','original'),
('113.18.c.3.C',3,'Which water body lies between Africa and Europe?','["the Mediterranean Sea", "the Arctic Ocean", "the Caribbean Sea", "the Gulf of Mexico"]'::jsonb,0,'It separates southern Europe from North Africa.','original'),
('113.18.c.3.D',2,'Which country is in East Asia?','["Poland", "Japan", "Peru", "Kenya"]'::jsonb,1,'Japan is in East Asia.','original'),
('113.18.c.3.D',2,'Which country is in Africa?','["Ukraine", "Chile", "Nigeria", "Thailand"]'::jsonb,2,'Nigeria is in West Africa.','original'),
('113.18.c.3.D',3,'Which country is in South America?','["India", "Egypt", "Norway", "Argentina"]'::jsonb,3,'Argentina is in South America.','original'),
('113.18.c.4.A',3,'Why might a factory be built near a seaport?','["ships can move raw materials and products cheaply", "ports are always inland", "ships cannot carry cargo", "ports have no goods"]'::jsonb,0,'Ports make shipping easy.','original'),
('113.18.c.4.A',3,'Where would farming most likely develop in a region?','["a frozen mountaintop", "an area with rivers and fertile soil", "a dry salt flat", "a barren cliff"]'::jsonb,1,'Water and soil support agriculture.','original'),
('113.18.c.4.B',3,'A mountain range between two countries can be a(n)...','["transportation corridor only", "bridge", "barrier to trade and travel", "ocean"]'::jsonb,2,'Mountains block movement.','original'),
('113.18.c.4.B',3,'A major river that carries barges is an example of a...','["barrier only", "cultural region", "desert", "transportation corridor"]'::jsonb,3,'Rivers move goods.','original'),
('113.18.c.5.A',3,'Which physical process has strongly affected people living along the Pacific ''Ring of Fire''?','["earthquakes and volcanoes", "blizzards only", "glacier retreat", "desertification"]'::jsonb,0,'Tectonic activity is frequent there.','original'),
('113.18.c.5.A',3,'Monsoon rains in South Asia affect people by...','["creating deserts", "bringing water for crops and sometimes floods", "freezing rivers", "stopping all farming"]'::jsonb,1,'Seasonal rains matter for farming.','original'),
('113.18.c.5.B',3,'People in very dry regions adapt by...','["growing rice paddies without water", "building ice rinks", "building wells and using irrigation", "avoiding all water"]'::jsonb,2,'Water systems help survival.','original'),
('113.18.c.5.B',3,'Houses built on stilts in flood-prone areas are an example of...','["a trade barrier", "modifying the environment", "ignoring the environment", "adapting to the environment"]'::jsonb,3,'Stilts keep homes above water.','original'),
('113.18.c.5.C',3,'Building a dam is an example of people...','["modifying the physical environment", "creating a climate", "avoiding the environment", "adapting only"]'::jsonb,0,'Dams change river flow.','original'),
('113.18.c.5.C',3,'Terrace farming on hillsides modifies the environment to...','["create deserts", "create flat fields for crops", "stop the rain", "cool the ocean"]'::jsonb,1,'Terraces make farmland on slopes.','original'),
('113.18.c.6.A',3,'In economics, ''capital'' means...','["a country''s flag", "the workers'' skills only", "tools, buildings and equipment used to make goods", "wild forests"]'::jsonb,2,'Capital goods produce other goods.','original'),
('113.18.c.6.A',3,'An entrepreneur is someone who...','["makes laws", "only works for wages", "collects taxes", "starts a business and takes risks"]'::jsonb,3,'Entrepreneurs organize production.','original'),
('113.18.c.6.B',4,'What problem can result from a shortage of skilled labor?','["factories cannot produce enough goods", "prices always fall", "farms disappear overnight", "oil becomes plentiful"]'::jsonb,0,'Fewer workers limit output.','original'),
('113.18.c.6.B',3,'A country with few natural resources may need to...','["eliminate money", "import resources from other countries", "close its schools", "stop all trade"]'::jsonb,1,'Trade fills resource gaps.','original'),
('113.18.c.6.C',3,'Why do countries trade with one another?','["trade is illegal", "borders do not exist", "no country has all the resources it needs", "every country has all resources"]'::jsonb,2,'Resource distribution is uneven.','original'),
('113.18.c.6.C',4,'Economic interdependence means countries...','["never trade", "have the same economy", "are fully self-sufficient", "rely on each other for goods and resources"]'::jsonb,3,'They depend on one another.','original'),
('113.18.c.7.A',3,'In a traditional economy, goods are mostly produced...','["following customs passed down over generations", "by central planners", "by free markets only", "by computers only"]'::jsonb,0,'Tradition guides production.','original'),
('113.18.c.7.A',3,'In a command economy, who decides what to produce?','["each consumer", "the government", "foreign companies", "each farmer individually"]'::jsonb,1,'Central authorities plan production.','original'),
('113.18.c.7.B',3,'In a free enterprise system, prices are mostly set by...','["a king", "a single planner", "supply and demand", "the military"]'::jsonb,2,'Markets set prices.','original'),
('113.18.c.7.B',4,'Which economy has the most government ownership of businesses?','["traditional village barter", "mixed market", "free enterprise", "communist"]'::jsonb,3,'Communism features state control.','original'),
('113.18.c.7.C',3,'Why is honesty important in a free enterprise system?','["buyers and sellers must be able to trust each other", "lying creates trust", "honesty slows trade", "contracts do not matter"]'::jsonb,0,'Ethics support markets.','original'),
('113.18.c.7.C',3,'A business that lies about the safety of its product is acting...','["ethically", "unethically", "as a government", "as a consumer"]'::jsonb,1,'Deception harms trust.','original'),
('113.18.c.8.A',2,'Farming and fishing are examples of which type of industry?','["retail", "manufacturing", "agricultural", "service"]'::jsonb,2,'They produce food from nature.','original'),
('113.18.c.8.A',3,'A bank, a hospital and a school are examples of which industry?','["mining", "agricultural", "manufacturing", "service"]'::jsonb,3,'They provide services, not goods.','original'),
('113.18.c.8.A',3,'A car factory belongs to which type of industry?','["manufacturing", "retail", "service", "agricultural"]'::jsonb,0,'It makes goods.','original'),
('113.18.c.8.B',3,'Which is an indicator of a country''s level of economic development?','["national anthem", "life expectancy", "number of holidays", "flag colors"]'::jsonb,1,'Health and income measure development.','original'),
('113.18.c.8.B',4,'A high literacy rate and a long life expectancy usually suggest a...','["colony", "less developed economy", "more developed economy", "traditional economy"]'::jsonb,2,'Education and health reflect development.','original'),
('113.18.c.9.A',3,'A constitutional government is an example of...','["unlimited government", "totalitarianism", "anarchy", "limited government"]'::jsonb,3,'A constitution limits power.','original'),
('113.18.c.9.A',3,'In a totalitarian government, power is held by...','["one leader or party with few limits", "local councils", "every citizen equally", "voters"]'::jsonb,0,'Unlimited power concentrates.','original'),
('113.18.c.9.B',3,'Why do societies limit government power?','["to make laws unenforceable", "to protect people''s rights and prevent abuse", "to end elections", "to remove courts"]'::jsonb,1,'Limits guard against tyranny.','original'),
('113.18.c.9.B',3,'Which document most often limits a government''s powers?','["a diary", "a price list", "a constitution", "a map"]'::jsonb,2,'It sets rules for government.','original'),
('113.18.c.9.C',4,'Which is an example of a human rights abuse by an unlimited government?','["holding free elections", "building public libraries", "funding hospitals", "jailing people for criticizing leaders"]'::jsonb,3,'Suppressing speech violates rights.','original'),
('113.18.c.9.C',3,'The Holocaust is an example of...','["genocide committed by a government", "a trade agreement", "a scientific discovery", "a peaceful election"]'::jsonb,0,'The Nazi regime murdered millions.','original'),
('113.18.c.10.A ',3,'A monarchy is rule by...','["foreign powers", "one person", "a council of citizens", "the many through voting"]'::jsonb,1,'A king or queen rules.','original'),
('113.18.c.10.A ',3,'An oligarchy is rule by...','["all citizens equally", "one person", "a few people", "no one"]'::jsonb,2,'A small group holds power.','original'),
('113.18.c.10.A ',3,'A democracy is rule by...','["a few nobles", "the military only", "one king", "the many"]'::jsonb,3,'Citizens share power.','original'),
('113.18.c.10.B',4,'Which is a way governments in India and Germany are similar?','["both are democracies with elected leaders", "both are communist", "both are absolute monarchies", "both have no courts"]'::jsonb,0,'Both hold elections.','original'),
('113.18.c.10.B',3,'Russia, China, Germany and India differ in how they...','["share one language", "organize government and choose leaders", "breathe air", "use the same constitution"]'::jsonb,1,'Governments vary.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g6_ss_v1'
from (values
('113.18.c.10.C',3,'Which ancient civilization is known for early forms of democracy?','["the Aztecs", "the Mongol Empire", "Athens in ancient Greece", "ancient Egypt"]'::jsonb,2,'Athenian citizens voted on laws.','original'),
('113.18.c.10.C',3,'The Roman Republic influenced modern governments with the idea of...','["no laws", "tribal chiefs only", "rule by one god-king", "representatives and written laws"]'::jsonb,3,'Rome used elected officials.','original'),
('113.18.c.11.A',3,'In many democracies, one responsibility of citizens is to...','["vote and obey laws", "ignore elections", "avoid all taxes", "break laws"]'::jsonb,0,'Citizens share duties.','original'),
('113.18.c.11.A',4,'How do citizen roles differ in a democracy versus a totalitarian state?','["democratic citizens cannot speak", "democratic citizens can influence government; others have few options", "there are no differences", "totalitarian citizens vote freely"]'::jsonb,1,'Participation varies.','original'),
('113.18.c.11.B',3,'Which allows citizens to influence the political process in a democracy?','["censorship", "secret police", "voting and free press", "banning protests"]'::jsonb,2,'These tools give voice.','original'),
('113.18.c.11.B',3,'In some countries, citizens have limited ability to change leaders. This is because...','["courts are independent", "laws protect speech", "everyone votes freely", "elections are controlled or absent"]'::jsonb,3,'Participation varies by system.','original'),
('113.18.c.12.A',3,'Why is civic participation important in representative governments?','["it helps keep leaders accountable", "it ends laws", "it removes elections", "it abolishes courts"]'::jsonb,0,'Participation is a civic duty.','original'),
('113.18.c.12.A',3,'Which is an example of civic participation?','["avoiding the news", "volunteering for a community cleanup", "ignoring a jury summons", "littering"]'::jsonb,1,'Helping the community is civic action.','original'),
('113.18.c.12.B',4,'In a representative government, rights come with...','["no courts", "fewer laws", "responsibilities", "no obligations"]'::jsonb,2,'Rights and duties are linked.','original'),
('113.18.c.12.B',3,'Serving on a jury is an example of a...','["treaty", "tax", "right to be ignored", "duty"]'::jsonb,3,'Citizens are required to serve.','original'),
('113.18.c.13.A',3,'Which is a trait that helps define a culture?','["shared language and traditions", "elevation", "average rainfall", "latitude"]'::jsonb,0,'Language and customs define cultures.','original'),
('113.18.c.13.A',3,'A culture region is an area where people share...','["only a river", "common traits such as language, religion or customs", "only a climate", "only a time zone"]'::jsonb,1,'Shared cultural traits mark a region.','original'),
('113.18.c.13.B',3,'A multicultural society is one in which...','["only one culture exists", "everyone speaks one language", "people of many cultures live together", "no one has a culture"]'::jsonb,2,'Several cultures coexist.','original'),
('113.18.c.13.C',3,'Immigrants often contribute to a society by bringing new...','["rivers", "oceans", "mountains", "foods, skills and ideas"]'::jsonb,3,'Diverse groups add to culture.','original'),
('113.18.c.13.C',4,'Why can diversity strengthen a society?','["different perspectives can lead to new ideas", "it removes all problems", "it prevents change", "it ends trade"]'::jsonb,0,'Diversity brings innovation.','original'),
('113.18.c.13.D',3,'Which is an example of cooperation between cultures?','["a trade war", "an international festival with shared performances", "a border dispute", "a ban on travel"]'::jsonb,1,'Cultural exchange fosters cooperation.','original'),
('113.18.c.13.D',3,'Disputes over land between ethnic groups are an example of...','["cultural cooperation", "diffusion by invention", "cultural conflict", "trade"]'::jsonb,2,'Competition can cause conflict.','original'),
('113.18.c.14.A',3,'Which is a basic institution found in all societies?','["a mountain", "a skateboard", "a coin", "family"]'::jsonb,3,'Family, government, education and religion are basic institutions.','original'),
('113.18.c.14.A',3,'Schools are an example of which kind of institution?','["educational", "military only", "economic", "religious"]'::jsonb,0,'They pass on knowledge.','original'),
('113.18.c.14.B',4,'Educational institutions differ in contemporary societies mainly in...','["whether people learn", "how schools are funded and organized", "whether the sun rises", "the number of oceans"]'::jsonb,1,'Characteristics vary by society.','original'),
('113.18.c.14.C',3,'How do religious institutions sustain themselves over time?','["by avoiding members", "by closing", "through teaching, ceremonies and donations", "by banning rituals"]'::jsonb,2,'Institutions endure by adapting and passing on traditions.','original'),
('113.18.c.15.A',3,'Cultural diffusion is the...','["end of trade", "freezing of rivers", "creation of mountains", "spread of ideas and customs from one culture to another"]'::jsonb,3,'Ideas travel with people.','original'),
('113.18.c.15.A',3,'Which is a means of cultural diffusion?','["trade", "tides", "glaciers", "lightning"]'::jsonb,0,'Trade moves ideas as well as goods.','original'),
('113.18.c.15.B',3,'Which factor speeds cultural change today?','["isolation", "improvements in communication and transportation", "fewer roads", "less travel"]'::jsonb,1,'Technology links cultures.','original'),
('113.18.c.15.C',3,'How has the internet affected cultures?','["it slows communication", "it eliminated all trade", "it lets ideas and media spread quickly across the world", "it ends languages overnight"]'::jsonb,2,'Technology speeds exchange.','original'),
('113.18.c.15.D',3,'Fast-food chains opening in many countries are an example of...','["a physical process", "a trade barrier", "cultural isolation", "cultural diffusion"]'::jsonb,3,'Business spreads customs.','original'),
('113.18.c.16.A',3,'Cathedrals, temples and mosques reflect a society''s...','["religious and cultural values", "river length", "weather only", "soil type"]'::jsonb,0,'Architecture expresses beliefs.','original'),
('113.18.c.16.A',3,'Folk songs often reflect a society''s...','["latitude", "history and traditions", "rainfall totals", "highest peaks"]'::jsonb,1,'Music conveys culture.','original'),
('113.18.c.16.B',4,'A protest song written during a social movement shows how...','["songs are random", "music has no meaning", "contemporary issues influence creative expression", "art ignores events"]'::jsonb,2,'Creators respond to events.','original'),
('113.18.c.16.C',3,'Which is a universal theme in art, music and literature?','["parking rules", "postal codes", "lawn maintenance", "justice"]'::jsonb,3,'Justice appears across cultures.','original'),
('113.18.c.17.A',3,'Religious ideas have influenced cultures by shaping...','["laws, holidays and values", "tides", "volcanoes", "rainfall"]'::jsonb,0,'Beliefs shape societies.','original'),
('113.18.c.17.B',3,'Ramadan is observed by followers of which religion?','["Hinduism", "Islam", "Judaism", "Buddhism"]'::jsonb,1,'It is a holy month of fasting in Islam.','original'),
('113.18.c.17.B',3,'Diwali is an important festival in which religion?','["Judaism", "Islam", "Hinduism", "Christianity"]'::jsonb,2,'Known as the festival of lights.','original'),
('113.18.c.17.B',3,'Passover is celebrated by followers of...','["Buddhism", "Islam", "Hinduism", "Judaism"]'::jsonb,3,'It remembers the Exodus.','original'),
('113.18.c.18.A',3,'Which invention most changed how people share printed information in medieval Europe?','["the printing press", "the telegraph", "the television", "the airplane"]'::jsonb,0,'Movable type spread books.','original'),
('113.18.c.18.A',3,'Which technology has most changed global communication in recent decades?','["the abacus", "the internet", "the sundial", "the wheelbarrow"]'::jsonb,1,'It links the world instantly.','original'),
('113.18.c.18.B',4,'Why might a poor country adopt new technology more slowly?','["technology is forbidden everywhere", "technology does not exist", "limited resources and funding", "it has too many resources"]'::jsonb,2,'Economics affects technology use.','original'),
('113.18.c.18.C',4,'Which is a reasonable prediction about widespread solar power?','["it will stop all trade", "it will end all weather", "it will eliminate the sun", "it could reduce reliance on fossil fuels"]'::jsonb,3,'Technology has social and environmental effects.','original'),
('113.18.c.19.A',3,'A letter written by a soldier during a war is a...','["primary source", "encyclopedia", "secondary source", "textbook"]'::jsonb,0,'Firsthand account.','original'),
('113.18.c.19.A',3,'A history textbook is an example of a...','["photograph from the event", "secondary source", "primary source", "diary"]'::jsonb,1,'Written later by others.','original'),
('113.18.c.19.B',3,'Putting events in the order they occurred is called...','["predicting", "voting", "sequencing", "categorizing"]'::jsonb,2,'Sequence orders events.','original'),
('113.18.c.19.C',3,'Which visual is best for showing how a population has changed over many years?','["a portrait", "a legend only", "a compass rose", "a line graph"]'::jsonb,3,'Line graphs show change over time.','original'),
('113.18.c.19.D',3,'Two newspapers describe the same protest very differently. This shows different...','["points of view", "time zones", "map scales", "latitudes"]'::jsonb,0,'People see issues differently.','original'),
('113.18.c.19.E',4,'Which is a claim supported by evidence?','["I think maybe.", "Trade increases a country''s access to goods because products move across borders.", "Trade is whatever.", "Countries exist."]'::jsonb,1,'A claim with reasoning.','original'),
('113.18.c.19.F',3,'To judge a source''s credibility, check...','["the cover color", "the font style", "the author''s qualifications and evidence", "the length only"]'::jsonb,2,'Credible sources show evidence.','original'),
('113.18.c.19.F',4,'A source that shows only one side of an issue may have...','["no words", "no author", "accuracy guaranteed", "bias"]'::jsonb,3,'Bias is a one-sided perspective.','original'),
('113.18.c.20.A',3,'Which question is a geographic question?','["Where is it located, and why is it there?", "Who sang it?", "What color is it?", "How old is the author?"]'::jsonb,0,'Geographers ask about location and why.','original'),
('113.18.c.20.B',4,'Population density maps help answer questions about...','["soccer rules", "distribution patterns of people", "rainbow colors", "song lyrics"]'::jsonb,1,'They show where people live.','original'),
('113.18.c.20.C',3,'To compare two countries'' populations, a student could use...','["a poem", "a recipe", "a bar graph of population data", "a diary"]'::jsonb,2,'Graphs compare data.','original'),
('113.18.c.20.D',3,'A thematic map shows...','["only roads", "only borders", "only the equator", "a specific theme such as rainfall or population"]'::jsonb,3,'Thematic maps focus on one topic.','original'),
('113.18.c.21.A',3,'The term ''culture'' refers to a group''s...','["shared way of life, including language, customs and beliefs", "soil", "rivers", "weather"]'::jsonb,0,'Culture is learned and shared.','original'),
('113.18.c.21.B',3,'A strong paragraph on a research topic includes a main idea and...','["a different topic", "supporting details", "random facts", "no details"]'::jsonb,1,'Support develops the main idea.','original'),
('113.18.c.21.E',3,'A citation in a report is used to...','["add a rhyme", "hide the author", "credit the source of the information", "lengthen the paper"]'::jsonb,2,'Citations avoid plagiarism.','original'),
('113.18.c.21.F',3,'Civil discourse means discussing topics with respect even when people...','["refuse to speak", "agree on everything", "shout over others", "disagree about the issue"]'::jsonb,3,'Respectful disagreement is civil.','original'),
('113.18.c.22.A',3,'Due process in a government means...','["people are treated fairly under the law", "decisions are secret", "trials are skipped", "laws apply only to some"]'::jsonb,0,'Fair legal procedures are required.','original'),
('113.18.c.22.A',3,'A caucus is a meeting where people...','["bake bread", "gather to choose candidates or discuss issues", "test machines", "draw maps"]'::jsonb,1,'Caucuses are part of the political process.','original'),
('113.18.c.22.B',4,'Which step comes after identifying a problem in decision-making?','["stop researching", "announce the result", "gather information", "ignore options"]'::jsonb,2,'Collect information before choosing.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
